//! Clipboard helpers shared by the history panel and finished recordings.

use std::path::Path;

use gpui_kit::{App, ClipboardItem, Image, ImageFormat};

/// Load an on-disk PNG / GIF off the UI thread before publishing it.
pub(crate) fn read_image_file(path: &Path, format: ImageFormat) -> anyhow::Result<Image> {
    Ok(Image::from_bytes(format, std::fs::read(path)?))
}

pub(crate) fn write_image(image: Image, cx: &App) {
    cx.write_to_clipboard(ClipboardItem::new_image(&image));
}

/// Remove one file generated by a copy task without touching any newer task's
/// clipboard backing file. Missing files are already clean.
pub(crate) fn remove_clipboard_file(path: &Path) {
    if let Err(error) = std::fs::remove_file(path)
        && error.kind() != std::io::ErrorKind::NotFound
    {
        log::warn!(
            "failed to remove clipboard image {}: {error}",
            path.display()
        );
    }
}

/// Keep the file currently referenced by the pasteboard across restarts. Only
/// older leftovers are eligible for age-based cleanup, and the newest managed
/// file is always retained (even when its timestamp cannot be read).
pub(crate) fn cleanup_clipboard_files(dir: &Path) {
    cleanup_clipboard_files_at(dir, std::time::SystemTime::now());
}

fn cleanup_clipboard_files_at(dir: &Path, now: std::time::SystemTime) {
    const MAX_AGE: std::time::Duration = std::time::Duration::from_secs(7 * 24 * 60 * 60);

    let Ok(entries) = std::fs::read_dir(dir) else {
        return;
    };
    let mut newest: Option<(std::time::SystemTime, std::path::PathBuf)> = None;
    let mut managed = Vec::new();
    for entry in entries.flatten() {
        let path = entry.path();
        if !path
            .file_name()
            .and_then(|name| name.to_str())
            .is_some_and(|name| {
                name.starts_with("snapit-copy-")
                    && name.ends_with(".png")
                    && entry.file_type().is_ok_and(|kind| kind.is_file())
            })
        {
            continue;
        }
        let modified = std::fs::metadata(&path)
            .ok()
            .and_then(|meta| meta.modified().ok());
        if let Some(modified) = modified
            && newest.as_ref().is_none_or(|(latest, latest_path)| {
                modified > *latest || (modified == *latest && path < *latest_path)
            })
        {
            newest = Some((modified, path.clone()));
        }
        managed.push((path, modified));
    }
    // If every timestamp failed, retain one deterministic file rather than
    // risking the pasteboard's only target.
    if newest.is_none()
        && let Some((path, _)) = managed.iter().min_by(|a, b| a.0.cmp(&b.0))
    {
        newest = Some((std::time::UNIX_EPOCH, path.clone()));
    }
    for (path, modified) in managed {
        if newest.as_ref().is_some_and(|(_, latest)| latest == &path) {
            continue;
        }
        let expired = modified
            .is_some_and(|modified| now.duration_since(modified).is_ok_and(|age| age > MAX_AGE));
        if expired && let Err(error) = std::fs::remove_file(&path) {
            log::warn!(
                "failed to remove stale clipboard image {}: {error}",
                path.display()
            );
        }
    }
}

/// What actually ended up on the clipboard, so callers can describe it honestly.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum FileCopy {
    /// A real file reference (`fileURL` / `CF_HDROP`): paste inserts the file.
    File,
    /// Only the path as text, because the native file reference failed.
    PathText,
}

/// Put a file on the clipboard so Finder / Explorer / chat apps paste the file
/// itself. Both platform backends ignore `ClipboardEntry::ExternalPaths` on
/// write, so the pasteboard (`fileURL`) / clipboard (`CF_HDROP`) is filled
/// directly. Returns `PathText` when only the path text could be written.
pub(crate) fn copy_file_reference(path: &Path, cx: &App) -> anyhow::Result<FileCopy> {
    #[cfg(target_os = "macos")]
    let native = copy_file_reference_macos(path);
    #[cfg(target_os = "windows")]
    let native = copy_file_reference_windows(path);
    // Unsupported targets are rejected by `main.rs`, but keep the function total
    // so adding a platform cannot turn into a missing-return type error.
    #[cfg(not(any(target_os = "macos", target_os = "windows")))]
    let native: anyhow::Result<()> = Err(anyhow::anyhow!(
        "no native file-reference clipboard backend"
    ));

    match native {
        Ok(()) => Ok(FileCopy::File),
        Err(err) => {
            // Windows may already have emptied the clipboard before it failed,
            // so always put something back and report what was actually written.
            log::warn!("clipboard file reference failed, copying the path as text: {err:#}");
            cx.write_to_clipboard(ClipboardItem::new_string(path.display().to_string()));
            Ok(FileCopy::PathText)
        }
    }
}

/// Explorer and chat apps read dropped files from `CF_HDROP`; the registered
/// "PNG"/"GIF" formats GPUI writes are images, not file references.
#[cfg(target_os = "windows")]
fn copy_file_reference_windows(path: &Path) -> anyhow::Result<()> {
    use std::os::windows::ffi::OsStrExt as _;

    use windows_sys::Win32::Foundation::{GlobalFree, POINT};
    use windows_sys::Win32::System::DataExchange::{
        CloseClipboard, EmptyClipboard, OpenClipboard, SetClipboardData,
    };
    use windows_sys::Win32::System::Memory::{
        GMEM_MOVEABLE, GMEM_ZEROINIT, GlobalAlloc, GlobalLock, GlobalUnlock,
    };
    use windows_sys::Win32::System::Ole::CF_HDROP;
    use windows_sys::Win32::UI::Shell::DROPFILES;

    // The file list is double-null-terminated UTF-16.
    let mut names: Vec<u16> = path.as_os_str().encode_wide().collect();
    names.push(0);
    names.push(0);
    let header = std::mem::size_of::<DROPFILES>();
    let size = header + names.len() * std::mem::size_of::<u16>();

    let mut opened = false;
    for _ in 0..5 {
        // The clipboard is a global resource other apps hold briefly.
        if unsafe { OpenClipboard(std::ptr::null_mut()) } != 0 {
            opened = true;
            break;
        }
        std::thread::sleep(std::time::Duration::from_millis(10));
    }
    anyhow::ensure!(opened, "OpenClipboard failed");

    let result = (|| -> anyhow::Result<()> {
        anyhow::ensure!(unsafe { EmptyClipboard() } != 0, "EmptyClipboard failed");
        let mem = unsafe { GlobalAlloc(GMEM_MOVEABLE | GMEM_ZEROINIT, size) };
        anyhow::ensure!(!mem.is_null(), "GlobalAlloc failed");
        let ptr = unsafe { GlobalLock(mem) };
        if ptr.is_null() {
            unsafe { GlobalFree(mem) };
            anyhow::bail!("GlobalLock failed");
        }
        let dropfiles = DROPFILES {
            pFiles: header as u32,
            pt: POINT { x: 0, y: 0 },
            fNC: 0,
            fWide: 1,
        };
        unsafe {
            std::ptr::write(ptr as *mut DROPFILES, dropfiles);
            std::ptr::copy_nonoverlapping(
                names.as_ptr(),
                (ptr as *mut u8).add(header) as *mut u16,
                names.len(),
            );
            GlobalUnlock(mem);
            if SetClipboardData(CF_HDROP as u32, mem).is_null() {
                GlobalFree(mem);
                anyhow::bail!("SetClipboardData(CF_HDROP) failed");
            }
        }
        // SetClipboardData succeeded — the clipboard owns the memory now.
        Ok(())
    })();
    unsafe { CloseClipboard() };
    result
}

#[cfg(target_os = "macos")]
fn copy_file_reference_macos(path: &Path) -> anyhow::Result<()> {
    use objc2::msg_send;
    use objc2::runtime::{AnyClass, AnyObject, Bool};
    use objc2_foundation::{NSArray, NSString, NSURL};

    // Spawning `osascript` for this took ~230 ms per copy and ran on the main
    // thread, which delayed every MP4 completion. The pasteboard API is a
    // sub-millisecond call and needs no extra dependency.
    let class = AnyClass::get(c"NSPasteboard")
        .ok_or_else(|| anyhow::anyhow!("NSPasteboard unavailable"))?;
    let pasteboard: *mut AnyObject = unsafe { msg_send![class, generalPasteboard] };
    anyhow::ensure!(!pasteboard.is_null(), "no general pasteboard");
    let url = NSURL::fileURLWithPath(&NSString::from_str(&path.to_string_lossy()));
    let objects = NSArray::from_retained_slice(&[url]);
    unsafe {
        let _: isize = msg_send![pasteboard, clearContents];
        let written: Bool = msg_send![pasteboard, writeObjects: &*objects];
        anyhow::ensure!(
            written == Bool::YES,
            "NSPasteboard refused {}",
            path.display()
        );
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::fs::FileTimes;
    use std::time::{Duration, SystemTime, UNIX_EPOCH};

    fn test_now() -> SystemTime {
        UNIX_EPOCH + Duration::from_secs(1_700_000_000)
    }

    fn test_dir() -> std::path::PathBuf {
        let nonce = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let dir = std::env::temp_dir().join(format!(
            "snapit-clipboard-test-{}-{nonce}",
            std::process::id()
        ));
        std::fs::create_dir_all(&dir).unwrap();
        dir
    }

    fn file_with_age(dir: &Path, name: &str, age: Duration) -> std::path::PathBuf {
        let path = dir.join(name);
        std::fs::write(&path, b"png").unwrap();
        let modified = test_now() - age;
        std::fs::File::options()
            .write(true)
            .open(&path)
            .unwrap()
            .set_times(FileTimes::new().set_modified(modified))
            .unwrap();
        path
    }

    #[test]
    fn startup_keeps_newest_clipboard_file_and_recent_other_instance_files() {
        let dir = test_dir();
        let expired = file_with_age(
            &dir,
            "snapit-copy-1-1-0.png",
            Duration::from_secs(30 * 86400),
        );
        let newest = file_with_age(&dir, "snapit-copy-2-2-0.png", Duration::from_secs(60));
        let other_instance =
            file_with_age(&dir, "snapit-copy-99-3-0.png", Duration::from_secs(120));
        let unmanaged = file_with_age(&dir, "other.png", Duration::from_secs(30 * 86400));

        cleanup_clipboard_files_at(&dir, test_now());

        assert!(!expired.exists());
        assert!(
            newest.exists(),
            "the newest file may back a persistent fileURL"
        );
        assert!(
            other_instance.exists(),
            "recent files may belong to another instance"
        );
        assert!(unmanaged.exists());
        std::fs::remove_dir_all(dir).unwrap();
    }

    #[test]
    fn age_cleanup_keeps_the_newest_file_even_when_it_is_expired() {
        let dir = test_dir();
        let expired = file_with_age(&dir, "snapit-copy-1.png", Duration::from_secs(30 * 86400));
        let newest = file_with_age(&dir, "snapit-copy-2.png", Duration::from_secs(10 * 86400));

        cleanup_clipboard_files_at(&dir, test_now());

        assert!(!expired.exists());
        assert!(newest.exists());
        std::fs::remove_dir_all(dir).unwrap();
    }

    #[test]
    fn startup_does_not_remove_recent_files_on_a_timestamp_tie() {
        let dir = test_dir();
        let first = file_with_age(&dir, "snapit-copy-b.png", Duration::ZERO);
        let second = file_with_age(&dir, "snapit-copy-a.png", Duration::ZERO);
        let times = FileTimes::new().set_modified(test_now() - Duration::from_secs(60));
        for path in [&first, &second] {
            std::fs::File::options()
                .write(true)
                .open(path)
                .unwrap()
                .set_times(times)
                .unwrap();
        }

        cleanup_clipboard_files_at(&dir, test_now());

        assert!(
            first.exists() && second.exists(),
            "recent files are not expired"
        );
        std::fs::remove_dir_all(dir).unwrap();
    }
}
